import json
import os
import uuid
from contextlib import asynccontextmanager
from datetime import datetime
from pathlib import Path
from urllib.parse import urlencode

from fastapi import APIRouter, Depends, FastAPI, Form, HTTPException, Query, UploadFile, status

from . import database_client, rabbitmq_client, rate_limit
from .deps import get_current_user, require_admin
from .schemas import Feedback, FeedbackTranscript, Question, Sentiment

AUDIO_STORAGE_DIR = Path(os.environ.get("AUDIO_STORAGE_DIR", "audio_uploads"))


@asynccontextmanager
async def lifespan(_: FastAPI):
    AUDIO_STORAGE_DIR.mkdir(parents=True, exist_ok=True)
    database_client.init_client()
    rate_limit.init_client()
    await rabbitmq_client.init_client()
    yield
    await rabbitmq_client.close_client()
    await rate_limit.close_client()
    await database_client.close_client()


app = FastAPI(lifespan=lifespan)
router = APIRouter(prefix="/api/feedback")


@app.get("/health")
async def health():
    return {"status": "ok"}


async def _store_audio(audio_file: UploadFile) -> str:
    suffix = Path(audio_file.filename or "").suffix
    stored_name = f"{uuid.uuid4()}{suffix}"
    destination = AUDIO_STORAGE_DIR / stored_name
    with destination.open("wb") as out:
        while chunk := await audio_file.read(1024 * 1024):
            out.write(chunk)
    return str(destination)


@router.post(
    "",
    response_model=Feedback,
    status_code=status.HTTP_201_CREATED,
    dependencies=[
        Depends(rate_limit.rate_limit_dependency("create_feedback", limit=20, window_seconds=60))
    ],
)
async def create_feedback(
    appointment_id: int = Form(...),
    answers: str = Form(default="[]"),
    audio_file: UploadFile | None = None,
    current_user: dict = Depends(get_current_user),
):
    appointment = await database_client.get_or_none(f"/appointments/{appointment_id}")
    if appointment is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="appointment not found")
    if appointment["user_id"] != current_user["id"]:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN, detail="not your appointment"
        )

    try:
        answers_payload = json.loads(answers)
    except ValueError:
        raise HTTPException(status_code=422, detail="answers must be valid JSON")
    if not isinstance(answers_payload, list):
        raise HTTPException(status_code=422, detail="answers must be a list")

    question_map = {}
    if appointment.get("hospital_id") is not None:
        questions = await database_client.get_or_none(
            f"/questions?hospital_id={appointment['hospital_id']}"
        )
        if questions:
            question_map = {q["id"]: q["text"] for q in questions}

    normalized_answers = []
    for item in answers_payload:
        try:
            qid = int(item["question_id"])
        except (KeyError, TypeError, ValueError):
            raise HTTPException(status_code=422, detail="each answer requires a question_id")
        question_text = question_map.get(qid) or item.get("question", "")
        normalized_answers.append(
            {
                "question_id": qid,
                "question": question_text,
                "rating": item.get("rating"),
                "comment": item.get("comment"),
            }
        )

    category_id = None
    if appointment.get("doctor_id") is not None:
        doctor = await database_client.get_or_none(f"/doctors/{appointment['doctor_id']}")
        if doctor is not None:
            category_id = doctor["medical_category_id"]

    stored_audio_path = await _store_audio(audio_file) if audio_file is not None else None

    created = await database_client.post(
        "/feedback",
        json={
            "user_id": current_user["id"],
            "appointment_id": appointment_id,
            "hospital_id": appointment.get("hospital_id"),
            "doctor_id": appointment.get("doctor_id"),
            "category_id": category_id,
            "answers": normalized_answers,
            "audio_file": stored_audio_path,
        },
    )

    if stored_audio_path is not None:
        await rabbitmq_client.publish_stt_job(created["id"], stored_audio_path)

    return created


@router.get("/questions/{appointment_id}", response_model=list[Question])
async def get_appointment_questions(
    appointment_id: int, current_user: dict = Depends(get_current_user)
):
    appointment = await database_client.get_or_none(f"/appointments/{appointment_id}")
    if appointment is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="appointment not found")
    if appointment["user_id"] != current_user["id"]:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN, detail="not your appointment"
        )
    if appointment.get("hospital_id") is None:
        return []
    questions = await database_client.get_or_none(
        f"/questions?hospital_id={appointment['hospital_id']}"
    )
    return questions or []


@router.get("/{feedback_id}", response_model=Feedback)
async def get_feedback(feedback_id: int, current_user: dict = Depends(get_current_user)):
    feedback = await database_client.get_or_none(f"/feedback/{feedback_id}")
    if feedback is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="feedback not found")
    if feedback["user_id"] != current_user["id"] and current_user["role"] != "admin":
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="not your feedback")
    return feedback


@router.get("", response_model=list[Feedback])
async def list_feedback(
    hospital_id: int | None = Query(default=None),
    category_id: int | None = Query(default=None),
    sentiment: Sentiment | None = Query(default=None),
    date_from: datetime | None = Query(default=None),
    date_to: datetime | None = Query(default=None),
    limit: int = Query(default=50, ge=1, le=200),
    offset: int = Query(default=0, ge=0),
    _: dict = Depends(require_admin),
):
    params = {
        k: v
        for k, v in {
            "hospital_id": hospital_id,
            "category_id": category_id,
            "sentiment": sentiment,
            "date_from": date_from.isoformat() if date_from else None,
            "date_to": date_to.isoformat() if date_to else None,
            "limit": limit,
            "offset": offset,
        }.items()
        if v is not None
    }
    return await database_client.get(f"/feedback?{urlencode(params)}")


@router.get("/{feedback_id}/transcript", response_model=FeedbackTranscript)
async def get_feedback_transcript(feedback_id: int, _: dict = Depends(require_admin)):
    transcript = await database_client.get_or_none(f"/feedback/{feedback_id}/transcript")
    if transcript is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="feedback not found")
    return transcript


app.include_router(router)

import { createFileRoute, Link } from '@tanstack/react-router'
import { useQuery, useMutation } from '@tanstack/react-query'
import { useState } from 'react'
import { toast } from 'sonner'
import {
  Smile,
  Sparkles,
  Timer,
  Handshake,
  CalendarCheck,
  Tag,
  MessageSquareText,
  Clock,
  CheckCircle2,
  ArrowLeft,
  Star,
} from 'lucide-react'

import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Checkbox } from '@/components/ui/checkbox'
import { Card, CardContent } from '@/components/ui/card'
import { PageLoader } from '@/components/shared/loader'
import { EmptyState } from '@/components/shared/empty-state'
import { VoiceRecorder } from '@/components/shared/voice-recorder'
import { requireAuth } from '@/lib/guards'
import { databaseApi, feedbackApi, hospitalsApi } from '@/lib/api'
import { formatDateTime } from '@/lib/format'
import { cn } from '@/lib/utils'
import type { LucideIcon } from 'lucide-react'

export const Route = createFileRoute('/feedback/$appointmentId')({
  beforeLoad: () => requireAuth(),
  component: FeedbackPage,
})

interface LikeTag {
  label: string
  icon: LucideIcon
}

const LIKE_TAGS: LikeTag[] = [
  { label: 'Friendly doctor', icon: Smile },
  { label: 'Clean facility', icon: Sparkles },
  { label: 'Short wait time', icon: Timer },
  { label: 'Polite staff', icon: Handshake },
  { label: 'Easy booking', icon: CalendarCheck },
  { label: 'Fair price', icon: Tag },
  { label: 'Clear explanation', icon: MessageSquareText },
  { label: 'On-time appointment', icon: Clock },
]

function FeedbackPage() {
  const { appointmentId } = Route.useParams()
  const id = Number(appointmentId)

  const [rating, setRating] = useState(0)
  const [tags, setTags] = useState<string[]>([])
  const [comment, setComment] = useState('')
  const [audio, setAudio] = useState<File | null>(null)
  const [consent, setConsent] = useState(false)
  const [submitted, setSubmitted] = useState(false)

  const appointment = useQuery({
    queryKey: ['appointment', id],
    queryFn: () => databaseApi.getAppointment(id),
  })
  const hospital = useQuery({
    queryKey: ['hospital', appointment.data?.hospital_id],
    queryFn: () => hospitalsApi.get(appointment.data!.hospital_id!),
    enabled: appointment.data?.hospital_id != null,
  })

  const submit = useMutation({
    mutationFn: () =>
      feedbackApi.submit({
        appointment_id: id,
        rating,
        tags,
        text_comment: comment || null,
        audio_file: audio,
      }),
    onSuccess: () => setSubmitted(true),
    onError: (error) => toast.error(error instanceof Error ? error.message : 'Submission failed'),
  })

  const toggleTag = (label: string) => {
    setTags((prev) => (prev.includes(label) ? prev.filter((t) => t !== label) : [...prev, label]))
  }

  if (appointment.isPending) return <PageLoader />
  if (appointment.isError || !appointment.data)
    return (
      <div className="mx-auto max-w-2xl px-4 py-10">
        <EmptyState title="Appointment not found" />
      </div>
    )

  if (submitted) {
    return (
      <div className="mx-auto max-w-xl px-4 py-16">
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-10 text-center">
            <CheckCircle2 className="size-14 text-emerald-500" />
            <h1 className="text-2xl font-semibold">Thank you for your feedback!</h1>
            <p className="max-w-sm text-sm text-muted-foreground">
              Your rating and {audio ? 'voice note' : 'review'} help other patients choose the right
              doctor. A discount reward from the admin will appear in your discounts wallet.
            </p>
            <div className="mt-2 flex gap-2">
              <Button render={<Link to="/discounts" />}>My discounts</Button>
              <Button variant="outline" render={<Link to="/profile/appointments" />}>
                Back to appointments
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-2xl px-4 py-10">
      <Button variant="ghost" size="sm" className="mb-4" render={<Link to="/profile/appointments" />}>
        <ArrowLeft className="size-4" /> My appointments
      </Button>

      <div className="mb-6">
        <h1 className="text-2xl font-semibold tracking-tight">How was your visit?</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          {hospital.data?.name ?? 'Your appointment'} · {formatDateTime(appointment.data.scheduled_at)}
        </p>
      </div>

      <div className="space-y-8">
        <section>
          <h2 className="mb-3 font-medium">
            1. Rating <span className="text-destructive">*</span>
          </h2>
          <div className="flex items-center gap-1">
            {[1, 2, 3, 4, 5].map((i) => (
              <button
                key={i}
                type="button"
                onClick={() => setRating(i)}
                className="transition-transform hover:scale-110"
                aria-label={`Rate ${i} star${i > 1 ? 's' : ''}`}
              >
                <Star
                  className={cn(
                    'size-9',
                    i <= rating ? 'fill-amber-400 text-amber-400' : 'fill-muted text-muted',
                  )}
                />
              </button>
            ))}
          </div>
        </section>

        <section>
          <h2 className="mb-3 font-medium">2. What did you like most?</h2>
          <div className="flex flex-wrap gap-2">
            {LIKE_TAGS.map(({ label, icon: Icon }) => {
              const active = tags.includes(label)
              return (
                <button
                  key={label}
                  type="button"
                  onClick={() => toggleTag(label)}
                  className={cn(
                    'flex items-center gap-2 rounded-full border px-3 py-1.5 text-sm font-medium transition-colors',
                    active
                      ? 'border-primary bg-primary text-primary-foreground'
                      : 'hover:border-ring hover:bg-muted',
                  )}
                >
                  <Icon className="size-4" />
                  {label}
                </button>
              )
            })}
          </div>
        </section>

        <section>
          <h2 className="mb-3 font-medium">3. Anything else? (optional)</h2>
          <Textarea
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            placeholder="Share more about your experience…"
            rows={4}
          />
        </section>

        <section>
          <h2 className="mb-3 font-medium">4. Voice feedback (optional)</h2>
          <VoiceRecorder onAudioReady={setAudio} />
          {audio && (
            <label className="mt-3 flex items-start gap-2 text-sm">
              <Checkbox checked={consent} onCheckedChange={(c) => setConsent(Boolean(c))} />
              <span className="text-muted-foreground">
                I consent to my voice recording being stored and processed for transcription
                (speech-to-text) in line with the personal data protection law.
              </span>
            </label>
          )}
        </section>

        <Button
          size="lg"
          className="w-full"
          disabled={rating === 0 || submit.isPending || (audio != null && !consent)}
          onClick={() => submit.mutate()}
        >
          {submit.isPending ? 'Submitting…' : 'Submit feedback'}
        </Button>
        {audio != null && !consent && (
          <p className="text-center text-xs text-destructive">
            Please consent to voice recording before submitting.
          </p>
        )}
      </div>
    </div>
  )
}

import { createFileRoute, useNavigate } from '@tanstack/react-router'
import { useQuery } from '@tanstack/react-query'
import { useMemo, useState } from 'react'
import { Trophy, ArrowUpDown, MapPin, Star, Search, X } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { PageLoader } from '@/components/shared/loader'
import { EmptyState } from '@/components/shared/empty-state'
import { useCategories } from '@/hooks/useCategories'
import { hospitalsApi } from '@/lib/api'
import type { HospitalLeaderboardEntry } from '@/lib/types'
import { Link } from '@tanstack/react-router'

interface LeaderboardSearch {
  q?: string
  category?: number
  city?: string
}

export const Route = createFileRoute('/leaderboard')({
  validateSearch: (search: Record<string, unknown>): LeaderboardSearch => ({
    q: typeof search.q === 'string' ? search.q : undefined,
    category: typeof search.category === 'number' ? search.category : undefined,
    city: typeof search.city === 'string' ? search.city : undefined,
  }),
  component: LeaderboardPage,
})

function LeaderboardPage() {
  const { q, category, city } = Route.useSearch()
  const navigate = useNavigate()
  const [sortBy, setSortBy] = useState<'score' | 'rating'>('score')
  const [localQuery, setLocalQuery] = useState(q ?? '')
  const { data: categories } = useCategories()

  const leaderboard = useQuery({
    queryKey: ['leaderboard', category],
    queryFn: () => hospitalsApi.leaderboard(category),
  })

  const cities = useMemo(() => {
    const list = leaderboard.data ?? []
    return [...new Set(list.map((h) => h.city))].sort()
  }, [leaderboard.data])

  const setSearch = (patch: Partial<LeaderboardSearch>) => {
    navigate({
      to: '/leaderboard',
      search: (prev: LeaderboardSearch) => ({ ...prev, ...patch }),
    })
  }

  const rows = useMemo(() => {
    let list = [...(leaderboard.data ?? [])]
    if (q) list = list.filter((h) => h.name.toLowerCase().includes(q.toLowerCase()))
    if (city) list = list.filter((h) => h.city === city)
    if (sortBy === 'rating') list.sort((a, b) => b.rating_avg - a.rating_avg)
    else list.sort((a, b) => b.weighted_score - a.weighted_score)
    return list.map((h, i) => ({ ...h, rank: i + 1 }))
  }, [leaderboard.data, q, city, sortBy])

  const submitSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setSearch({ q: localQuery.trim() || undefined })
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-10">
      <div className="mb-8 flex flex-col gap-4">
        <div className="flex items-center gap-3">
          <span className="flex size-10 items-center justify-center rounded-xl bg-primary text-primary-foreground">
            <Trophy className="size-5" />
          </span>
          <div>
            <h1 className="text-2xl font-semibold">Hospital leaderboard</h1>
            <p className="text-sm text-muted-foreground">
              Ranked by a weighted score of reputation and distance.
            </p>
          </div>
        </div>

        <div className="flex flex-col gap-3">
          <form onSubmit={submitSearch} className="relative max-w-md">
            <Search className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={localQuery}
              onChange={(e) => setLocalQuery(e.target.value)}
              placeholder="Search by hospital name…"
              className="pl-9"
            />
          </form>

          <div className="flex flex-wrap items-center gap-2">
            <Button
              variant={category === undefined ? 'default' : 'outline'}
              size="sm"
              onClick={() => setSearch({ category: undefined })}
            >
              All
            </Button>
            {(categories ?? []).map((c) => (
              <Button
                key={c.id}
                variant={category === c.id ? 'default' : 'outline'}
                size="sm"
                onClick={() => setSearch({ category: c.id })}
              >
                {c.name}
              </Button>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <div className="flex items-center gap-1 rounded-lg border px-1.5 py-1">
              <Button
                variant={sortBy === 'score' ? 'secondary' : 'ghost'}
                size="xs"
                onClick={() => setSortBy('score')}
              >
                <ArrowUpDown className="size-3" /> Score
              </Button>
              <Button
                variant={sortBy === 'rating' ? 'secondary' : 'ghost'}
                size="xs"
                onClick={() => setSortBy('rating')}
              >
                <Star className="size-3" /> Rating
              </Button>
            </div>

            <select
              value={city ?? ''}
              onChange={(e) => setSearch({ city: e.target.value || undefined })}
              className="h-8 rounded-lg border border-input bg-background px-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <option value="">All cities</option>
              {cities.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>

            {(q || city || category !== undefined) && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => navigate({ to: '/leaderboard', search: {} })}
              >
                <X className="size-3.5" /> Clear filters
              </Button>
            )}
          </div>
        </div>
      </div>

      {leaderboard.isPending ? (
        <PageLoader />
      ) : leaderboard.isError ? (
        <EmptyState
          title="Could not load the leaderboard"
          description="The hospitals service may be offline. Try again later."
        />
      ) : rows.length === 0 ? (
        <EmptyState title="No hospitals found" description="Try adjusting your filters." />
      ) : (
        <div className="divide-y rounded-xl border">
          {rows.map((entry: HospitalLeaderboardEntry & { rank: number }) => (
            <RankRow key={entry.id} entry={entry} />
          ))}
        </div>
      )}
    </div>
  )
}

function RankRow({ entry }: { entry: HospitalLeaderboardEntry & { rank: number } }) {
  return (
    <Link
      to="/hospitals/$hospitalId"
      params={{ hospitalId: String(entry.id) }}
      className="flex items-center gap-4 px-4 py-3.5 transition-colors hover:bg-muted/50"
    >
      <span className="w-8 shrink-0 text-center text-lg font-semibold text-muted-foreground">
        {entry.rank <= 3 ? (
          <span
            className={
              entry.rank === 1
                ? 'text-amber-500'
                : entry.rank === 2
                  ? 'text-slate-400'
                  : 'text-orange-400'
            }
          >
            {entry.rank}
          </span>
        ) : (
          entry.rank
        )}
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate font-medium">{entry.name}</p>
        <p className="flex items-center gap-1 text-sm text-muted-foreground">
          <MapPin className="size-3" /> {entry.city}
        </p>
      </div>
      <div className="flex shrink-0 flex-col items-end gap-1">
        <Badge variant="secondary">
          <Star className="size-3 fill-amber-400 text-amber-400" /> {entry.rating_avg.toFixed(1)}
        </Badge>
        <span className="text-xs text-muted-foreground">
          score {entry.weighted_score.toFixed(2)}
        </span>
      </div>
    </Link>
  )
}

import { API, apiWsUrl } from './config'
import { useAuthStore } from '@/stores/auth'
import type {
  Appointment,
  AppointmentStatus,
  AuditLogEntry,
  CategoryVisitStat,
  CheckoutResponse,
  Discount,
  DoctorSummary,
  Feedback,
  FeedbackSentiment,
  FeedbackTranscript,
  Hospital,
  HospitalDetail,
  HospitalLeaderboardEntry,
  MedicalCategory,
  Notification,
  PaymentDetail,
  PaymentProvider,
  QueueEntry,
  SortOption,
  StatsOverview,
  TokenResponse,
  User,
} from './types'

export class ApiError extends Error {
  status: number
  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

type QueryParams = Record<string, string | number | boolean | null | undefined>

export function buildQuery(params?: QueryParams | object): string {
  if (!params) return ''
  const qs = new URLSearchParams()
  for (const [key, value] of Object.entries(params)) {
    if (value === null || value === undefined || value === '') continue
    qs.set(key, String(value))
  }
  const s = qs.toString()
  return s ? `?${s}` : ''
}

async function apiFetch<T>(base: string, path: string, options: RequestInit = {}): Promise<T> {
  const token = useAuthStore.getState().token
  const headers = new Headers(options.headers)
  if (token) headers.set('Authorization', `Bearer ${token}`)
  if (options.body && !(options.body instanceof FormData)) {
    headers.set('Content-Type', 'application/json')
  }

  const res = await fetch(`${base}${path}`, { ...options, headers })

  if (!res.ok) {
    let message = res.statusText
    try {
      const data = await res.json()
      if (typeof data?.detail === 'string') message = data.detail
      else if (data?.detail) message = JSON.stringify(data.detail)
    } catch {
      /* ignore parse errors */
    }
    throw new ApiError(res.status, message)
  }

  if (res.status === 204) return undefined as T
  return (await res.json()) as T
}

/* ------------------------------------------------------------------ */
/* Auth                                                                */
/* ------------------------------------------------------------------ */

export const authApi = {
  register: (body: {
    full_name: string
    username: string
    phone?: string
