            json={
                "user_id": user["id"],
                "appointment_id": appointment["id"],
                "hospital_id": hospital["id"],
                "answers": [
                    {"question_id": question["id"], "question": question["text"], "rating": 4}
                ],
            },
        )
    ).json()
